import {Engine} from './analysis.js';
import {attackArrows,engineCaptureArrows,verifiedBest,displayArrows,readArrowOptions,saveArrowOptions} from './review-arrows.js';
import {studyFromQuery} from './opening-study.js';
import {Chess} from './vendor/chess.js';import {drawBoard} from './mini-board.js';import {escapeHTML as esc} from './settings.js';
const $=id=>document.getElementById(id);let catalog=[],current=null,moves=[],index=0,flipped=false;
let focus=null,shown,engine,pending=null;const results=new Map();
const opts=readArrowOptions();$('arrowMode').value=opts.mode;$('showControlSquares').checked=opts.empty;
function paint(){
 if(!shown)return;const fen=shown.fen(),mode=$('arrowMode').value,source=results.get(fen),wantBest=['both','best'].includes(mode),wantAttacks=['both','attacks'].includes(mode);
 const prev=shown.history({verbose:true}).at(-1),sq=focus||prev?.to;
 const attacks=wantAttacks&&sq?attackArrows(fen,sq,$('showControlSquares').checked):[];
 const best=verifiedBest(fen,source),caps=best?engineCaptureArrows(fen,source):[],rec=caps.find(a=>a.kind==='recommended');
 displayArrows($('openingBoard'),$('arrowLegend'),[...attacks,...(wantAttacks?caps.filter(a=>a.kind==='favorable'):[]),...(wantBest&&best?[rec||{...best,kind:'next',label:'Migliore per chi deve muovere'}]:[])],flipped);
 $('checkOpeningMove').hidden=!wantBest;$('checkOpeningMove').disabled=!!pending||!!best||shown.isGameOver();
 $('openingArrowStatus').textContent=mode==='off'?'':pending===fen?'Analisi in corso…':wantBest&&!best?(source?'Analisi insufficiente per indicare la migliore.':'Migliore non verificata per questa posizione.'):(wantAttacks?'Tocca un pezzo per osservarne gli attacchi.':'');
}
$('checkOpeningMove').onclick=async()=>{if(pending||!shown)return;const fen=shown.fen();pending=fen;paint();try{engine??=new Engine(()=>{});const r=await engine.evaluate(fen,'deep','',{limits:[18,6000]});results.set(fen,r)}catch{results.set(fen,{})}finally{pending=null;paint()}};
for(const id of ['arrowMode','showControlSquares'])$(id).onchange=()=>{saveArrowOptions($('arrowMode').value,$('showControlSquares').checked);paint()};
$('openingBoard').addEventListener('click',e=>{const sq=e.target.closest('[data-sq]')?.dataset.sq;if(!shown||!sq)return;focus=focus===sq||!shown.get(sq)?null:sq;board()});
function board(){if(!current)return;const c=new Chess(current.startFen);for(const m of moves.slice(0,index))c.move(m);if(shown?.fen()!==c.fen())focus=null;shown=c;drawBoard($('openingBoard'),c,{flipped,selected:focus,disabled:false,last:c.history({verbose:true}).at(-1)});paint();$('openingPly').textContent=`${index} / ${moves.length}`;$('openingBack').disabled=index===0;$('openingNext').disabled=index===moves.length;$('openingNotation').textContent=c.history().map((m,i)=>(i%2===0?`${i/2+1}. `:'')+m).join(' ')||'Posizione iniziale'}
function choose(id){current=catalog.find(o=>o.id===id);const c=new Chess();c.loadPgn(current.pgn);moves=c.history();current.startFen=c.history({verbose:true})[0]?.before;index=0;$('openingEco').textContent=current.eco+' · '+current.category;$('openingName').textContent=current.name;$('openingIdea').textContent=current.idea;$('openingCaution').textContent=current.caution;board();list()}
function list(){const q=$('openingSearch').value.toLowerCase(),cat=$('openingFilter').value;const items=catalog.filter(o=>(cat==='all'||o.category===cat)&&[o.name,o.sourceName,o.eco,...o.tags].join(' ').toLowerCase().includes(q));$('openingCount').textContent=`${items.length} aperture mostrate`;$('openingList').innerHTML=items.map(o=>`<button class="opening-card ${current?.id===o.id?'selected-opening':''}" data-opening="${o.id}"><span>${esc(o.eco)} · ${o.category==='gambetto'?'GAMBETTO':'APERTURA'}</span><strong>${esc(o.name)}</strong><p>${esc(o.idea)}</p></button>`).join('')||'<p>Nessuna apertura corrisponde alla ricerca.</p>';document.querySelectorAll('[data-opening]').forEach(b=>b.onclick=()=>{choose(b.dataset.opening);if(innerWidth<700)document.querySelector('.opening-detail').scrollIntoView({behavior:'smooth',block:'start'})})}
$('openingSearch').oninput=list;$('openingFilter').onchange=list;$('openingBack').onclick=()=>{index=Math.max(0,index-1);board()};$('openingNext').onclick=()=>{index=Math.min(moves.length,index+1);board()};$('openingFlip').onclick=()=>{flipped=!flipped;board()};$('openingReview').onclick=()=>{if(!current)return;try{const review=new Chess();review.loadPgn(current.pgn);review.setHeader('Event','Studio: '+current.name);review.setHeader('Result','*');localStorage.setItem('plystreak-review-import',review.pgn());localStorage.removeItem('plystreak-review-id');localStorage.removeItem('plystreak-review-side');location.href='index.html?training=1'}catch{$('openingStatus').textContent='Memoria non disponibile: copia la sequenza e importala nella revisione.'}};
fetch('vendor/opening-catalog.json').then(r=>{if(!r.ok)throw Error('Catalogo non disponibile. Ricarica la pagina.');return r.json()}).then(data=>{catalog=data;return (new URLSearchParams(location.search).has('pgn')?fetch('vendor/openings.json').then(r=>{if(!r.ok)throw Error('Repertorio non disponibile. Riprova più tardi.');return r.json()}).then(book=>{const lesson=studyFromQuery(location.search,book,catalog);if(lesson){catalog.unshift(lesson);$('openingStatus').textContent='Sequenza riconosciuta dalla tua partita. Usa le frecce per studiarla; la revisione resta aperta nella scheda precedente.';choose(lesson.id)}}):Promise.resolve(choose(catalog[0].id)))}).catch(e=>{$('openingStatus').textContent=e.message;if(catalog.length)choose(catalog[0].id)});
